-- Sistem Pemantauan Magang dan KP - skema + data demo (MySQL 8 / MariaDB 10.4+)
-- Buat database kosong dulu (utf8mb4), pilih database itu, lalu import file ini.
SET NAMES utf8mb4; SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `activity_logs`,`report_reviews`,`report_versions`,`internship_reports`,`logbook_reviews`,`logbook_attachments`,`logbooks`,`supervisions`,`internships`,`lecturer_profiles`,`student_profiles`,`sessions`,`password_reset_tokens`,`users`,`migrations`;

CREATE TABLE `migrations` (`id` int unsigned NOT NULL AUTO_INCREMENT, `migration` varchar(255) NOT NULL, `batch` int NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `role` enum('admin','dosen','mahasiswa') NOT NULL DEFAULT 'mahasiswa',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_role_index` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `password_reset_tokens` (`email` varchar(255) NOT NULL, `token` varchar(255) NOT NULL, `created_at` timestamp NULL DEFAULT NULL, PRIMARY KEY (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sessions` (
  `id` varchar(255) NOT NULL, `user_id` bigint unsigned DEFAULT NULL, `ip_address` varchar(45) DEFAULT NULL, `user_agent` text,
  `payload` longtext NOT NULL, `last_activity` int NOT NULL,
  PRIMARY KEY (`id`), KEY `sessions_user_id_index` (`user_id`), KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `student_profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `user_id` bigint unsigned NOT NULL, `nim` varchar(30) NOT NULL,
  `program_studi` varchar(100) NOT NULL, `no_hp` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `student_profiles_user_id_unique` (`user_id`), UNIQUE KEY `student_profiles_nim_unique` (`nim`),
  CONSTRAINT `student_profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `lecturer_profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `user_id` bigint unsigned NOT NULL, `nidn` varchar(30) NOT NULL,
  `program_studi` varchar(100) NOT NULL, `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `lecturer_profiles_user_id_unique` (`user_id`), UNIQUE KEY `lecturer_profiles_nidn_unique` (`nidn`),
  CONSTRAINT `lecturer_profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `internships` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `student_id` bigint unsigned NOT NULL, `nama_perusahaan` varchar(255) NOT NULL,
  `alamat` varchar(255) DEFAULT NULL, `pembimbing_lapangan` varchar(255) DEFAULT NULL,
  `tanggal_mulai` date NOT NULL, `tanggal_selesai` date NOT NULL,
  `status` enum('belum_mulai','berjalan','selesai') NOT NULL DEFAULT 'belum_mulai',
  `target_logbook` smallint unsigned NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), KEY `internships_student_id_status_index` (`student_id`,`status`),
  CONSTRAINT `internships_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `supervisions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `lecturer_id` bigint unsigned NOT NULL, `internship_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `supervisions_internship_id_unique` (`internship_id`),
  CONSTRAINT `supervisions_lecturer_id_foreign` FOREIGN KEY (`lecturer_id`) REFERENCES `users` (`id`),
  CONSTRAINT `supervisions_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `logbooks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `internship_id` bigint unsigned NOT NULL, `tanggal` date NOT NULL,
  `judul` varchar(255) NOT NULL, `deskripsi` text NOT NULL, `hasil` text, `kendala` text, `rencana_tindak_lanjut` text,
  `status` enum('draft','menunggu','disetujui','perlu_revisi') NOT NULL DEFAULT 'draft',
  `submission_number` smallint unsigned NOT NULL DEFAULT 0, `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), KEY `logbooks_internship_id_status_index` (`internship_id`,`status`), KEY `logbooks_internship_id_tanggal_index` (`internship_id`,`tanggal`),
  CONSTRAINT `logbooks_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `logbook_attachments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `logbook_id` bigint unsigned NOT NULL, `path` varchar(255) NOT NULL,
  `nama_asli` varchar(255) NOT NULL, `mime` varchar(100) NOT NULL, `ukuran` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), CONSTRAINT `logbook_attachments_logbook_id_foreign` FOREIGN KEY (`logbook_id`) REFERENCES `logbooks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `logbook_reviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `logbook_id` bigint unsigned NOT NULL, `reviewer_id` bigint unsigned NOT NULL,
  `submission_number` smallint unsigned NOT NULL, `keputusan` enum('disetujui','perlu_revisi') NOT NULL,
  `komentar` text, `snapshot` json DEFAULT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `logbook_reviews_logbook_id_created_at_index` (`logbook_id`,`created_at`),
  CONSTRAINT `logbook_reviews_logbook_id_foreign` FOREIGN KEY (`logbook_id`) REFERENCES `logbooks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `logbook_reviews_reviewer_id_foreign` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `internship_reports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `internship_id` bigint unsigned NOT NULL,
  `status` enum('belum_diunggah','menunggu','perlu_revisi','disetujui') NOT NULL DEFAULT 'belum_diunggah',
  `versi_terbaru` smallint unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `internship_reports_internship_id_unique` (`internship_id`), KEY `internship_reports_status_index` (`status`),
  CONSTRAINT `internship_reports_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `report_versions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `report_id` bigint unsigned NOT NULL, `versi` smallint unsigned NOT NULL,
  `path` varchar(255) NOT NULL, `nama_asli` varchar(255) NOT NULL, `ukuran` int unsigned NOT NULL,
  `uploaded_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), UNIQUE KEY `report_versions_report_id_versi_unique` (`report_id`,`versi`),
  CONSTRAINT `report_versions_report_id_foreign` FOREIGN KEY (`report_id`) REFERENCES `internship_reports` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `report_reviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `report_version_id` bigint unsigned NOT NULL, `reviewer_id` bigint unsigned NOT NULL,
  `keputusan` enum('disetujui','perlu_revisi') NOT NULL, `komentar` text, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `report_reviews_report_version_id_foreign` FOREIGN KEY (`report_version_id`) REFERENCES `report_versions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `report_reviews_reviewer_id_foreign` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `activity_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `user_id` bigint unsigned DEFAULT NULL, `internship_id` bigint unsigned DEFAULT NULL,
  `aksi` varchar(60) NOT NULL, `subject_type` varchar(255) DEFAULT NULL, `subject_id` bigint unsigned DEFAULT NULL,
  `metadata` json DEFAULT NULL, `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`), KEY `activity_logs_user_id_created_at_index` (`user_id`,`created_at`),
  KEY `activity_logs_internship_id_created_at_index` (`internship_id`,`created_at`), KEY `activity_logs_subject_type_subject_id_index` (`subject_type`,`subject_id`),
  CONSTRAINT `activity_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `activity_logs_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;
SET FOREIGN_KEY_CHECKS=0;
SET FOREIGN_KEY_CHECKS=1;
